//! The "scaffolded, not implemented" error channel for `com-amazonaws-mediapackage-mediapackage`.
//!
//! @generated by the emulator core scaffold op-stub generator.
//!
//! Every generated operation stub returns [`Scaffolded::not_implemented`], which the
//! framework renders as a protocol-correct **HTTP 501 `NotImplemented`**. Do not change
//! a stub to return a success value: a client, and any check that only asserts the call
//! succeeded, cannot tell an empty success from a real implementation. Implement the
//! operation, or leave the 501.
//!
//! ## The error type
//!
//! A stub's error type is `Scaffolded<{Op}ErrorModeled>` — the model's own error enum
//! plus the `NotImplemented` variant. Do not try to add `NotImplemented` to the
//! `#[operation_error]` enum directly; it accepts only variants the model declares.
//!
//! ## Implementing an operation
//!
//! Replace the `Err(..)` in the handler body with real behaviour. Each stub emits a
//! CONCRETE `impl From<{Op}ErrorModeled> for {Op}Error` beside its
//! alias, so `?` works through the wrapper and a modeled failure needs no ceremony:
//!
//! ```ignore
//! return Err(GetThingErrorModeled::ResourceNotFound(
//!     ResourceNotFound { message: Some("no such thing".into()) },
//! )
//! .into());
//! ```
//!
//! That impl is emitted per operation, not once for all of them — keep it that way if
//! you edit a stub.
//!
//! ## Once the operation is implemented
//!
//! Keep the `#[operation_error]` enum, the alias and the `From` impl.
//!
//! An implemented operation stops needing the 501, but the wrapper is also the only
//! place it can return an error its own model does not declare — `validation` above,
//! for a service whose model carries no client-input error. Delete the wrapper and the
//! handler has no way to refuse a bad request at all.

use aws_smithy_schema::serde::{SerdeError, SerializableStruct, ShapeSerializer};
use aws_smithy_schema::{Schema, ShapeId, ShapeType};
use smithy_server_runtime::OperationError;

/// The `message` member of the synthetic `NotImplemented` error shape.
///
/// `with_xml_name("Message")` matches the casing the restXml / awsQuery error
/// envelopes use, so the same value renders correctly on the XML protocols and as
/// lowercase `message` on the JSON/CBOR ones.
static NOT_IMPLEMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#NotImplemented$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `NotImplemented` error shape.
///
/// Deliberately in the `smithy.framework` namespace: this shape is NOT in any
/// service's model, so it must not collide with a modeled shape. The wire `__type` /
/// `<Code>` comes from [`OperationError::shape_name`] below, not from this schema.
pub static NOT_IMPLEMENTED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#NotImplemented",
        "smithy.framework",
        "NotImplemented",
    ),
    ShapeType::Structure,
    &[&NOT_IMPLEMENTED_MESSAGE],
);

/// The payload of a `NotImplemented` failure: which operation was called, and the
/// fact that it is scaffolded rather than broken.
#[derive(Debug, Clone)]
pub struct NotImplemented {
    pub message: String,
}

impl NotImplemented {
    /// A `NotImplemented` naming `operation`.
    ///
    /// The wording matters: it must read as "not written yet", never as "the emulator
    /// is broken", because that distinction is what a human triaging a failing fixture
    /// needs first.
    pub fn new(operation: &str) -> Self {
        Self {
            message: format!(
                "operation {operation} is scaffolded but not implemented in this emulator"
            ),
        }
    }
}

impl std::fmt::Display for NotImplemented {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NotImplemented: {}", self.message)
    }
}

impl std::error::Error for NotImplemented {}

impl SerializableStruct for NotImplemented {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&NOT_IMPLEMENTED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ValidationException` error shape.
static VALIDATION_EXCEPTION_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ValidationException$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ValidationException` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model, so it must not collide with a modeled one.
/// If THIS service's model declares its own `ValidationException`, prefer that —
/// see [`Scaffolded::validation`].
pub static VALIDATION_EXCEPTION_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ValidationException",
        "smithy.framework",
        "ValidationException",
    ),
    ShapeType::Structure,
    &[&VALIDATION_EXCEPTION_MESSAGE],
);

/// The payload of a `ValidationException`: why the request was refused.
#[derive(Debug, Clone)]
pub struct ValidationException {
    pub message: String,
}

impl ValidationException {
    /// A `ValidationException` carrying `message`.
    ///
    /// Say what was wrong with the request and name the member, the way the
    /// boundary validator does — the caller has to fix the request from this text
    /// alone.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ValidationException {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ValidationException: {}", self.message)
    }
}

impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

// =============================================================================
// MediaPackage's own error envelope: `message` AND `errors`
// =============================================================================
//
// A MediaPackage error body carries the `message` sentence the model declares, and —
// for a failure the service reports AGAINST A KEY — an `errors` object keyed by the
// thing that was wrong: a resource type for a resource that is missing or in the way, a
// request member for a value the service will not accept, whose value reports the
// reasons for that key (see [`Reasons`] for the two shapes a recorded body uses). The
// model declares only `Message` on each error shape, so the generated
// error structs (`NotFoundException`, `UnprocessableEntityException`, …) cannot carry
// the second member: they are generated from the model and a field that is not a
// modelled member does not exist on them.
//
// [`ServiceError`] is that envelope, and it travels on the error channel as
// [`Scaffolded::Service`]. It carries the MODELLED error's wire code and HTTP status
// (so a client branches exactly as the model says) and renders the body members
// from the per-key reasons it was built with — including the `message`, which is
// built FROM those reasons rather than written twice, so the sentence and the
// structured map can never disagree.
//
// Some refusals this service answers are worded as ONE sentence of the service's own,
// stating no key and no per-key reason at all ([`ServiceError::unprocessable_sentence`]).
// Those carry that sentence as `message` and no `errors` member, because there is no key
// the failure is reported against: inventing one would put prose in the body the service
// does not state.
//
// The wording of each reason — what a missing resource, a duplicate id or a refused
// member says — lives in `crate::state`, beside the rest of this service's
// request-derived text.

/// The `message` member of this service's error envelope: the sentence, built from
/// the envelope's per-key reasons.
static SERVICE_ERROR_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#MediaPackageError$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_json_name("message")
.with_xml_name("Message");

/// The `errors` member of this service's error envelope: an object keyed by the resource
/// type or request member the failure is about, whose value reports that key's reasons —
/// a bare requirement string or a list, as [`Reasons`] describes. Absent from the body of
/// a refusal the service words as one sentence of its own, which reports no key.
///
/// One member schema serves the map, its keys and its list values: the JSON codec reads
/// a member schema for the BODY KEY it emits and for nothing else (list elements and map
/// entries carry no key of their own), which is also how the generated serializers write
/// a modelled map member.
static SERVICE_ERROR_ERRORS: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#MediaPackageError$errors",
        "smithy.framework",
        "errors",
    ),
    ShapeType::Map,
    "errors",
    1,
)
.with_json_name("errors")
.with_xml_name("Errors");

/// Schema for this service's error envelope.
///
/// In the `smithy.framework` namespace for the same reason as [`NOT_IMPLEMENTED_SCHEMA`]:
/// the shape is not in the model (the model declares the error shapes, each with
/// `Message` alone), so it must not collide with a modelled one. ONE schema serves every
/// MediaPackage error because a schema shapes only the BODY; the wire error code and the
/// HTTP status travel beside it, on the [`ServiceError`] itself.
pub static SERVICE_ERROR_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#MediaPackageError",
        "smithy.framework",
        "MediaPackageError",
    ),
    ShapeType::Structure,
    &[&SERVICE_ERROR_MESSAGE, &SERVICE_ERROR_ERRORS],
);

/// `NotFoundException`'s wire error code — the shape name, which restJson1 puts in
/// `x-amzn-errortype` and in the body's `__type`.
pub const NOT_FOUND_CODE: &str = "NotFoundException";
/// `NotFoundException`'s modelled status (`httpError` 404 on
/// `com.amazonaws.mediapackage#NotFoundException`).
pub const NOT_FOUND_STATUS: u16 = 404;
/// `UnprocessableEntityException`'s wire error code.
pub const UNPROCESSABLE_ENTITY_CODE: &str = "UnprocessableEntityException";
/// `UnprocessableEntityException`'s modelled status (`httpError` 422 on
/// `com.amazonaws.mediapackage#UnprocessableEntityException`).
pub const UNPROCESSABLE_ENTITY_STATUS: u16 = 422;
/// `TooManyRequestsException`'s wire error code.
pub const TOO_MANY_REQUESTS_CODE: &str = "TooManyRequestsException";
/// `TooManyRequestsException`'s modelled status (`httpError` 429 on
/// `com.amazonaws.mediapackage#TooManyRequestsException`).
pub const TOO_MANY_REQUESTS_STATUS: u16 = 429;

/// What an `errors` entry reports for its key.
///
/// MediaPackage reports a failure one of two ways, and the recorded bodies show both:
///
/// * the REQUEST VALIDATOR — the step that reads the request before anything is looked up
///   — reports the ONE requirement a member failed, as a bare string
///   (`"errors": {"maxResults": "must be an integer between 1 and 50"}`);
/// * everything decided against STATE — a resource that is missing, an id in use,
///   children blocking a delete, a reference the service cannot resolve — reports a LIST
///   of reasons for its key (`"errors": {"channel": ["with id=… not found"]}`).
///
/// So the shape of the value says which kind of failure it is, and a client reading one
/// key gets the same structure for every failure of that kind.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Reasons {
    /// The single requirement a request member failed, as the request validator reports
    /// it.
    Requirement(String),
    /// The reasons a key carries, as everything decided against state reports them.
    List(Vec<String>),
}

impl Reasons {
    /// The reasons, whichever way they are reported — what the sentence states.
    fn each(&self) -> &[String] {
        match self {
            Self::Requirement(requirement) => std::slice::from_ref(requirement),
            Self::List(reasons) => reasons.as_slice(),
        }
    }
}

/// One MediaPackage error: a modelled error's code and status, plus the per-key reasons
/// its body reports in `errors` and states in `message`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServiceError {
    /// The modelled error shape's name — the wire error code.
    code: &'static str,
    /// That shape's modelled `httpError` status.
    status: u16,
    /// The ONE sentence this error class states, for a refusal the service words itself
    /// rather than reporting against a key. `None` for every keyed failure, whose
    /// sentence is built from [`Self::errors`].
    sentence: Option<String>,
    /// The reasons, by the resource type or request member each is about. A `BTreeMap`,
    /// so the body's key order is the keys' own order rather than an insertion or hash
    /// order: one failure renders the same bytes every time. Empty exactly when
    /// [`Self::sentence`] is set.
    errors: std::collections::BTreeMap<String, Reasons>,
}

impl ServiceError {
    /// An error of the modelled shape `code`/`status`, reporting `reasons` for `key`.
    fn new(code: &'static str, status: u16, key: &str, reasons: Reasons) -> Self {
        let mut errors = std::collections::BTreeMap::new();
        errors.insert(key.to_string(), reasons);
        Self {
            code,
            status,
            sentence: None,
            errors,
        }
    }

    /// `NotFoundException` (404): the resource the request addressed does not exist.
    pub fn not_found(key: &str, reason: impl Into<String>) -> Self {
        Self::new(
            NOT_FOUND_CODE,
            NOT_FOUND_STATUS,
            key,
            Reasons::List(vec![reason.into()]),
        )
    }

    /// `UnprocessableEntityException` (422) for something decided against STATE: an id
    /// already in use, children blocking a delete, a reference that cannot be resolved.
    /// Reports a LIST of reasons for `key` — see [`Reasons`].
    pub fn unprocessable_state(key: &str, reason: impl Into<String>) -> Self {
        Self::new(
            UNPROCESSABLE_ENTITY_CODE,
            UNPROCESSABLE_ENTITY_STATUS,
            key,
            Reasons::List(vec![reason.into()]),
        )
    }

    /// `UnprocessableEntityException` (422) from the REQUEST VALIDATOR: the one
    /// requirement `member` failed, reported as a bare string — see [`Reasons`].
    pub fn unprocessable_member(member: &str, requirement: impl Into<String>) -> Self {
        Self::new(
            UNPROCESSABLE_ENTITY_CODE,
            UNPROCESSABLE_ENTITY_STATUS,
            member,
            Reasons::Requirement(requirement.into()),
        )
    }

    /// `UnprocessableEntityException` (422) stating `sentence` — the whole wording this
    /// service answers one class of refusal with, reported against no key.
    ///
    /// For a refusal the service words as its own fixed sentence rather than as a
    /// requirement some member failed: the sentence is the error class's text, so it is
    /// stated verbatim and the body carries no `errors` entry to go with it.
    pub fn unprocessable_sentence(sentence: impl Into<String>) -> Self {
        Self {
            code: UNPROCESSABLE_ENTITY_CODE,
            status: UNPROCESSABLE_ENTITY_STATUS,
            sentence: Some(sentence.into()),
            errors: std::collections::BTreeMap::new(),
        }
    }

    /// `TooManyRequestsException` (429): "The client has exceeded their resource or
    /// throttling limits".
    pub fn too_many_requests(key: &str, reason: impl Into<String>) -> Self {
        Self::new(
            TOO_MANY_REQUESTS_CODE,
            TOO_MANY_REQUESTS_STATUS,
            key,
            Reasons::List(vec![reason.into()]),
        )
    }

    /// The sentence this error states: the error class's own wording when it has one,
    /// otherwise each reason after the key it is about, so the `message` and the `errors`
    /// map say the same thing in the same words.
    pub fn message(&self) -> String {
        if let Some(sentence) = &self.sentence {
            return sentence.clone();
        }
        self.errors
            .iter()
            .flat_map(|(key, reasons)| {
                reasons
                    .each()
                    .iter()
                    .map(move |reason| format!("{key} {reason}"))
            })
            .collect::<Vec<String>>()
            .join("; ")
    }

    /// The wire error code (the modelled shape's name).
    pub fn code(&self) -> &'static str {
        self.code
    }

    /// The modelled HTTP status.
    pub fn status(&self) -> u16 {
        self.status
    }

    /// The reasons this error reports, by key — what the body's `errors` member carries.
    pub fn errors(&self) -> &std::collections::BTreeMap<String, Reasons> {
        &self.errors
    }
}

impl std::fmt::Display for ServiceError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message())
    }
}

impl std::error::Error for ServiceError {}

impl SerializableStruct for ServiceError {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&SERVICE_ERROR_MESSAGE, self.message().as_str())?;
        // A refusal worded as one sentence reports no key, so the body carries `message`
        // alone rather than an empty object.
        if self.errors.is_empty() {
            return Ok(());
        }
        s.write_map(&SERVICE_ERROR_ERRORS, &|entries| {
            for (key, reasons) in &self.errors {
                entries.write_string(&SERVICE_ERROR_ERRORS, key.as_str())?;
                match reasons {
                    // A requirement is the value itself, not a one-element list.
                    Reasons::Requirement(requirement) => {
                        entries.write_string(&SERVICE_ERROR_ERRORS, requirement.as_str())?;
                    }
                    Reasons::List(reasons) => {
                        entries.write_list(&SERVICE_ERROR_ERRORS, &|list| {
                            for reason in reasons {
                                list.write_string(&SERVICE_ERROR_ERRORS, reason.as_str())?;
                            }
                            Ok(())
                        })?;
                    }
                }
            }
            Ok(())
        })?;
        Ok(())
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// A modelled error carrying this service's full body — `message` AND the per-key
    /// `errors` map every MediaPackage error reports. Renders with the code and status
    /// the envelope carries, which are the modelled shape's own.
    ///
    /// Reach for this for every client-visible refusal: the generated error structs
    /// carry `Message` alone, because that is all the model declares, so a refusal
    /// returned as [`Modeled`](Self::Modeled) answers with half the envelope.
    Service(ServiceError),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }
}

/// Lets a handler write `Err(crate::state::channel_not_found(id).into())`: the envelope
/// is the same whichever operation raises it, so every operation's error channel takes
/// it without naming the wrapper variant.
impl<E> From<ServiceError> for Scaffolded<E> {
    fn from(error: ServiceError) -> Self {
        Self::Service(error)
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::Service(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::Service(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::Service(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::Service(_) => &SERVICE_ERROR_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The modelled shape the envelope was built for, which is where its status
            // comes from too — so code and status cannot disagree.
            Self::Service(e) => e.code(),
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::Service(e) => e.status(),
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // MediaPackage is restJson1 and its model carries no `awsQueryError`
            // trait on any error shape, so there is no legacy query code to name.
            Self::Service(_) => None,
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::ValidationException(_) => None,
        }
    }
}
